/**
 * Writes `src/generated/installedPacks.ts` — the barrel that turns "which
 * content packs does this checkout have" into a build fact you can read in a
 * file.
 *
 *   node scripts/generate-installed-packs.mjs            # write
 *   node scripts/generate-installed-packs.mjs --check    # fail if stale
 *
 * ## Why a generated file rather than a dynamic import
 *
 * `src/content/install.ts` is Stage 1's pack loader and spec §9.1's one file
 * Stage 2 replaces. Its shape — a static array of factories, resolved
 * synchronously — is load-bearing: `spellRegistry.ts` reads `BUNDLED_PACK_ID`
 * from it at module scope, and `Game` builds a match plan synchronously.
 * Making the riot pack optional therefore cannot mean making the *import*
 * conditional; nothing in ESM lets a static import be conditional. What it
 * can mean is that the list of static imports is itself generated, which is
 * this repository's own idiom already: `src/generated/assetManifest.ts`,
 * `spellCatalog.ts` and `spellModules.ts` are all exactly this.
 *
 * ## Why the barrel names packs by package name
 *
 * Not a style preference. Nothing in this repository currently resolves
 * either pack by its package name — core reaches both by relative path
 * (`../../packs/riot/pack`), which is a path that resolves to nothing the day
 * the pack is a repository of its own and `npm install` puts it under
 * `node_modules/`. This barrel is the first place that has to be true, and
 * emitting `@moba2d/content-riot/pack` is also the only thing in the build
 * that exercises the workspace links at all.
 *
 * ## What it does not do
 *
 * It does not emit the reference pack. See `scripts/installed-packs.mjs`'s
 * `CORE_OWN` for why: that pack is not optional, `install.ts` imports it
 * plainly, and listing it here would install it twice. Its name is still in
 * `installedPackNames`, which answers the *other* question.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { installedContentPackages, optionalContentPackages } from './installed-packs.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outputPath = join(root, 'src', 'generated', 'installedPacks.ts');
const check = process.argv.includes('--check');

/**
 * The two files a pack has to publish for the barrel to be able to name it.
 * Checked here, by path, so a pack whose layout drifted fails with its own
 * name in the message rather than as an unresolved specifier in `tsc`'s
 * output three steps later.
 */
const REQUIRED = [
  ['pack', 'pack.ts'],
  ['generated/assetManifest', join('generated', 'assetManifest.ts')],
];

const packs = optionalContentPackages(root);
for (const pack of packs) {
  for (const [specifier, file] of REQUIRED) {
    if (!existsSync(join(pack.dir, file))) {
      throw new Error(
        `${pack.packageName} is installed but has no ${file} — the barrel would emit ` +
          `\`${pack.packageName}/${specifier}\`, which resolves to nothing`
      );
    }
  }
}

const names = installedContentPackages(root).map(pack => pack.name);

const imports = packs
  .flatMap(pack => [
    `import ${pack.name}Code, {\n  data as ${pack.name}Data,\n  BUNDLED_PACK_ID as ${pack.name}PackId,\n} from '${pack.packageName}/pack';`,
    `import { assetManifest as ${pack.name}AssetManifest } from '${pack.packageName}/generated/assetManifest';`,
  ])
  .join('\n');

const entries = packs
  .map(
    pack => `  {
    id: ${pack.name}PackId,
    name: '${pack.name}',
    packageName: '${pack.packageName}',
    data: ${pack.name}Data,
    code: ${pack.name}Code,
    assetManifest: ${pack.name}AssetManifest,
  },`
  )
  .join('\n');

const source = `// Generated by scripts/generate-installed-packs.mjs. Do not edit.
//
// Which optional content packs this checkout has installed, named by package
// name so the specifier keeps resolving once a pack is a repository of its
// own. \`src/content/install.ts\` is the read side; \`tests/setup.ts\` reads the
// same list so the suite and the app cannot disagree about which packs exist.
//
// Regenerate with \`npm run packs:generate\`; \`npm run packs:check\` (in
// \`verify\`) fails if this file has drifted from what is actually installed.
import type { ContentPackData, ContentPackFactory } from '@/content/ContentPack';
import type { PackAssetManifest } from '@/managers/AssetManager';
${imports ? `${imports}\n` : ''}
/** One installed pack, with both halves and its own generated asset manifest. */
export interface InstalledPack {
  /** The id the pack's own manifest declares — \`'riot'\`. */
  readonly id: string;
  /** The pack's local name, i.e. its package name without the \`@moba2d/content-\` prefix. */
  readonly name: string;
  /** The specifier this file imports it by. */
  readonly packageName: string;
  readonly data: ContentPackData;
  readonly code: ContentPackFactory;
  readonly assetManifest: PackAssetManifest;
}

/**
 * Install order. Sorted by package name, which is stable across machines —
 * \`readdirSync\` order is not. Today there is at most one entry, so ordering
 * is theoretical; it stops being theoretical the moment a third pack exists.
 */
export const installedPacks: InstalledPack[] = [
${entries}
];

/**
 * Every installed content pack's local name, \`reference\` included — the
 * answer to "which packs does this checkout have", as opposed to
 * \`installedPacks\`, which answers "which packs does \`install.ts\` have to be
 * told about". \`tests/support/installedPacks.ts\` is the read side.
 */
export const installedPackNames: readonly string[] = [${names.map(name => `'${name}'`).join(', ')}];
`;

const existing = existsSync(outputPath) ? readFileSync(outputPath, 'utf8') : '';

if (check) {
  if (existing !== source) {
    console.error(
      `src/generated/installedPacks.ts is out of date — installed packs are ` +
        `[${names.join(', ')}]. Run \`npm run packs:generate\`.`
    );
    process.exit(1);
  }
  console.log(`installed packs ok: [${names.join(', ')}]`);
} else if (existing === source) {
  console.log(`installed packs unchanged: [${names.join(', ')}]`);
} else {
  writeFileSync(outputPath, source);
  console.log(`wrote src/generated/installedPacks.ts: [${names.join(', ')}]`);
}
